SET XACT_ABORT ON;\nBEGIN TRANSACTION;\n\nUPDATE dbo.Prompt SET Category = N'animals'\nWHERE Kind = 'word' AND Text IN (\n    'dog','cat','horse','cow','pig','sheep','goat','rabbit','mouse','lion','tiger','bear','elephant','monkey','giraffe','zebra','fox','wolf','deer',\n    N'pies',N'kot',N'koń',N'krowa',N'świnia',N'owca',N'koza',N'królik',N'mysz',N'lew',N'tygrys',N'niedźwiedź',N'słoń',N'małpa',N'żyrafa',N'zebra',N'lis',N'wilk',N'jeleń'\n);\nUPDATE dbo.Prompt SET Category = N'food'\nWHERE Kind = 'word' AND Text IN (\n    'apple','banana','orange','bread','cheese','pizza','cake','egg','carrot','potato','tomato','chocolate','cookie','rice','milk','coffee','tea',\n    N'jabłko',N'banan',N'pomarańcza',N'chleb',N'ser',N'pizza',N'ciasto',N'jajko',N'marchew',N'ziemniak',N'pomidor',N'czekolada',N'ciastko',N'ryż',N'mleko',N'kawa',N'herbata'\n);\nUPDATE dbo.Prompt SET Category = N'objects'\nWHERE Kind = 'word' AND Text IN (\n    'chair','table','lamp','phone','book','key','watch','umbrella','pencil','scissors','bottle','camera','computer','keyboard','bicycle',\n    N'krzesło',N'stół',N'lampa',N'telefon',N'książka',N'klucz',N'zegarek',N'parasol',N'ołówek',N'nożyczki',N'butelka',N'aparat',N'komputer',N'klawiatura',N'rower'\n);\n\nDECLARE @Prompts TABLE (Text NVARCHAR(120), Language NVARCHAR(5), Category NVARCHAR(64), Kind VARCHAR(16));\nINSERT INTO @Prompts VALUES\n('break the ice','en',N'idioms','saying'),\n('piece of cake','en',N'idioms','saying'),\n('raining cats and dogs','en',N'idioms','saying'),\n('the early bird catches the worm','en',N'proverbs','saying'),\n('better late than never','en',N'proverbs','saying'),\n('two heads are better than one','en',N'proverbs','saying'),\n('walking the dog','en',N'everyday activities','phrase'),\n('making breakfast','en',N'everyday activities','phrase'),\n('washing the car','en',N'everyday activities','phrase'),\n('missing the bus','en',N'everyday situations','phrase'),\n('birthday party','en',N'events','phrase'),\n('treasure hunt','en',N'games','phrase'),\n('building a snowman','en',N'activities','phrase'),\n('taking a selfie','en',N'everyday activities','phrase'),\n('opening a present','en',N'events','phrase'),\n('playing hide and seek','en',N'games','phrase'),\n(N'bułka z masłem','pl',N'powiedzenia','saying'),\n(N'robić z igły widły','pl',N'powiedzenia','saying'),\n(N'leje jak z cebra','pl',N'powiedzenia','saying'),\n(N'lepiej późno niż wcale','pl',N'przysłowia','saying'),\n(N'co dwie głowy to nie jedna','pl',N'przysłowia','saying'),\n(N'nie chwal dnia przed zachodem słońca','pl',N'przysłowia','saying'),\n(N'wyprowadzać psa','pl',N'codzienne czynności','phrase'),\n(N'robić śniadanie','pl',N'codzienne czynności','phrase'),\n(N'myć samochód','pl',N'codzienne czynności','phrase'),\n(N'spóźnić się na autobus','pl',N'codzienne sytuacje','phrase'),\n(N'przyjęcie urodzinowe','pl',N'wydarzenia','phrase'),\n(N'poszukiwanie skarbu','pl',N'gry','phrase'),\n(N'lepić bałwana','pl',N'czynności','phrase'),\n(N'robić selfie','pl',N'codzienne czynności','phrase'),\n(N'otwierać prezent','pl',N'wydarzenia','phrase'),\n(N'bawić się w chowanego','pl',N'gry','phrase');\n\nINSERT INTO dbo.Prompt (Text, Language, Category, Kind)\nSELECT source.Text, source.Language, source.Category, source.Kind\nFROM @Prompts source\nWHERE NOT EXISTS (\n    SELECT 1 FROM dbo.Prompt target\n    WHERE target.Text = source.Text AND target.Language = source.Language\n);\n\nCOMMIT;\n
